Repair the following GNU C++11 code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
There is the faculty of Computer Science in Berland. In the social net "TheContact!" for each course of this faculty there is the special group whose name equals the year of university entrance of corresponding course of students at the university. Each of students joins the group of his course and joins all groups for which the year of student's university entrance differs by no more than x from the year of university entrance of this student, where x — some non-negative integer. A value x is not given, but it can be uniquely determined from the available data. Note that students don't join other groups. You are given the list of groups which the student Igor joined. According to this information you need to determine the year of Igor's university entrance.
</problem_description>

Here is the GNU C++11 code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <random>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    // Randomized quicksort to avoid worst-case behavior
    mt19937 rng(random_device{}());
    uniform_int_distribution<int> dist(1, n);

    function<void(int, int)> qsort;
    qsort = [&](int l, int r) {
        if (l >= r) return;

        // Choose random pivot
        int pivot_idx = dist(rng) % (r - l + 1) + l;
        int pivot = a[pivot_idx];
        swap(a[pivot_idx], a[l]);

        int i = l, j = r;
        do {
            while (i <= r && a[i] < pivot) ++i;
            while (j >= l && a[j] > pivot) --j;
            if (i <= j) {
                swap(a[i], a[j]);
                ++i; --j;
            }
        } while (i <= j);

        qsort(l, j);
        qsort(i, r);
    };

    qsort(1, n);
    cout << a[(1 + n) / 2];
    return 0;
}
</original_code>
